import numpy as np
def equation(t, x, v, params):
    w = 0.4035
    c = np.cos(w*t); s = np.sin(w*t)
    return (params[0] + params[1]*x + params[2]*v + params[3]*np.sqrt(x) + params[4]*np.sin(v)
            + params[5]*v*v + params[6]*c + params[7]*s + params[8]*c*np.sqrt(x) + params[9]*c*v)
